import pandas as pd


def run(inputs: dict) -> dict:
    target = inputs["target_snapshot"]
    events = inputs["cdc_events"]
    watermark = inputs["watermark"]

    # Determine watermark high_ts
    if len(watermark) > 0 and pd.notna(watermark["high_ts"].iloc[0]):
        high_ts = watermark["high_ts"].iloc[0]
    else:
        high_ts = pd.Timestamp.min

    # Only events strictly after the watermark are new and need to be applied
    new_events = events[events["event_ts"] > high_ts].copy()

    # Apply events sequentially per item in (event_ts, event_seq) order
    new_events = new_events.sort_values(
        by=["event_ts", "event_seq"], kind="mergesort"
    )

    # Build initial state from target_snapshot
    state = {}
    for _, row in target.iterrows():
        state[row["item_id"]] = {
            "qty_on_hand": float(row["qty_on_hand"]),
            "last_event_ts": row["last_event_ts"],
        }

    for _, row in new_events.iterrows():
        item_id = row["item_id"]
        op = row["op"]
        qty = row["qty"]
        ts = row["event_ts"]

        if op == "R":
            # Receipt: accumulate qty; if item doesn't exist, (re)create starting from 0
            if item_id in state:
                state[item_id]["qty_on_hand"] = state[item_id]["qty_on_hand"] + qty
            else:
                state[item_id] = {"qty_on_hand": 0.0 + qty, "last_event_ts": ts}
            state[item_id]["last_event_ts"] = ts
        elif op == "A":
            # Adjustment: absolute reset; (re)creates item if delisted/absent
            state[item_id] = {"qty_on_hand": qty, "last_event_ts": ts}
        elif op == "D":
            # Delete: remove item from snapshot entirely
            if item_id in state:
                del state[item_id]
        else:
            # Unknown op codes are ignored (no-op) to be safe
            continue

    if state:
        result = pd.DataFrame(
            [
                {
                    "item_id": k,
                    "qty_on_hand": v["qty_on_hand"],
                    "last_event_ts": v["last_event_ts"],
                }
                for k, v in state.items()
            ]
        )
    else:
        result = pd.DataFrame(columns=["item_id", "qty_on_hand", "last_event_ts"])

    result["item_id"] = result["item_id"].astype("int64")
    result["qty_on_hand"] = result["qty_on_hand"].astype("float64")
    result["last_event_ts"] = pd.to_datetime(result["last_event_ts"]).astype(
        "datetime64[us]"
    )

    return {"new_snapshot": result}
